/**
 * Provincias de España como trazados SVG, para el mapa del área de cliente.
 *
 * NO se escriben a mano: están generados una sola vez a partir del TopoJSON
 * público de `es-atlas` (INE), proyectado con `d3-geo` (cónica conforme,
 * paralelos 40°/43°) sobre un lienzo de 331×220, que es el hueco que el Figma
 * reserva para el mapa. Los paquetes se usaron solo para generar este archivo
 * y no forman parte del prototipo.
 *
 * Canarias va en un recuadro aparte abajo a la izquierda (`canarias: true`),
 * como es costumbre en los mapas de España: si se proyectase en su sitio real
 * la península quedaría diminuta. En el Figma el mapa es una imagen fija de la
 * península; el recuadro se añade para que esas dos provincias también se
 * puedan pintar.
 */

/** Medidas del lienzo del mapa. El SVG usa este viewBox. */
export const MAPA_ANCHO = 331;
export const MAPA_ALTO = 220;

export type Provincia = {
  /** Nombre tal y como lo publica el INE. Es la clave que usan los datos mock. */
  nombre: string;
  /** Si va en el recuadro de Canarias en vez de en la península. */
  canarias: boolean;
  /** Centro geográfico de la provincia, en el mismo lienzo. Ahí va el marcador. */
  cx: number;
  cy: number;
  /** Trazado SVG de la provincia. */
  d: string;
};

